#include <bits/stdc++.h>
using namespace std;

#define LOOP(i,st,ed) for(int i=st;i<=ed;++i)
#define REV(i,st,ed) for(int i=st;i>=ed;--i)
typedef long long ll;

inline int getInt() {
    int x=0,f=1;char c;
    while((c=getchar()) && (c<'0'||c>'9') && c!='-');
    if(c=='-'){f=-1;c=getchar();}
    do {x=(x<<3)+(x<<1)+(c^'0');} while((c=getchar())>='0' && c<='9');
    return x*f;
}

inline ll getLong() {
    ll x=0,f=1;char c;
    while((c=getchar()) && (c<'0'||c>'9') && c!='-');
    if(c=='-'){f=-1;c=getchar();}
    do {x=(x<<3)+(x<<1)+(c^'0');} while((c=getchar())>='0' && c<='9');
    return x*f;
}

const int MAXN=32,MOD=1e9+7;

inline void update(int &x,int y){
    x+=y;
    if(x>=MOD) x-=MOD;
}

struct Matrix {
    int mat[MAXN][MAXN];
    void clear() {
        memset(mat,0,sizeof(mat));
    }
    void display() {
        for(int i=1;i<=n+1;++i){
            for(int j=1;j<=n+1;++j){
                printf("%d%c",mat[i][j],j==n+1?'\n':' ');
            }
        }
        putchar('\n');
    }
    Matrix operator*(const Matrix &rhs) const {
        Matrix res; res.clear();
        for(int i=1;i<=n+1;++i)
            for(int j=1;j<=n+1;++j)
                for(int k=1;k<=n+1;++k)
                    update(res.mat[i][j],(long long)mat[i][k]*rhs.mat[k][j]%MOD);
        return res;
    }
};

int n;
Matrix identity, matrixA[MAXN], prefix[MAXN], suffix[MAXN], result;

int main() {
#ifndef ONLINE_JUDGE
    freopen("matrix.in","r",stdin);
    freopen("matrix.out","w",stdout);
#endif
    ll m= getLong(); n= getInt();
    identity.clear();
    for(int i=1;i<=n;++i) identity.mat[i][i]=1;
    result=identity;
    for(int i=1;i<=n;++i){
        matrixA[i]=identity;
        matrixA[i].mat[i][i]=1;
    }
    prefix[0]=identity; suffix[n+1]=identity;
    for(;m; m/=n){
        ll u=m%n;
        if(u){
            ll s=0;
            for(ll v=m;v;v/=n) s=(s+v/n)%n;
            u=(s+u-1)%n+1;
            for(;u!=s;--u){
                if(u<=0) u+=n;
                result=matrixA[u]*result;
            }
        }
        for(int i=1;i<=n;++i) prefix[i]=prefix[i-1]*matrixA[i];
        for(int i=n;i>=1;--i) suffix[i]=matrixA[i]*suffix[i+1];
        for(int i=1;i<=n;++i) matrixA[i]=suffix[i]*prefix[i-1];
    }
    int total=1;
    for(int i=1;i<=n;++i) update(total,result.mat[n+1][i]);
    printf("%d\n",total);
    return 0;
}
